.sky-announcement {
  display: grid;
  width: 100%;
  min-height: 22px;
  overflow: hidden;
  color: #fff;
  font-size: 13px;
  line-height: 22px;
  text-align: center;
}

.sky-announcement-item {
  grid-area: 1 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
  opacity: 0;
  animation: sky-message-cycle 12s linear infinite;
}

.sky-announcement-item:nth-child(1) {
  animation-delay: 0s;
}

.sky-announcement-item:nth-child(2) {
  animation-delay: 4s;
}

.sky-announcement-item:nth-child(3) {
  animation-delay: 8s;
}

@keyframes sky-message-cycle {
  0%, 30% {
    opacity: 1;
    transform: translateY(0);
  }

  33.33%, 100% {
    opacity: 0;
    transform: translateY(-100%);
  }
}

@media (max-width: 768px) {
  .sky-announcement {
    min-height: 20px;
    font-size: 12px;
    line-height: 20px;
  }
}
.sky-message-1 {
  animation-delay: 0s !important;
}

.sky-message-2 {
  animation-delay: 4s !important;
}

.sky-message-3 {
  animation-delay: 8s !important;
}
.sky-announcement {
  position: relative;
  left: 50%;
  width: 100vw !important;
  margin-left: -50vw;
  min-height: 28px;
  font-size: 15px;
  font-weight: 500;
  line-height: 28px;
}
@media (max-width: 767px) {
  body .mobile-scroll ul.products,
  body ul.products.mobile-scroll {
    display: flex !important;
    flex-wrap: nowrap !important;
    gap: 12px !important;
    overflow-x: auto !important;
    padding-right: 16px !important;
  }

  body .mobile-scroll ul.products > li.product,
  body ul.products.mobile-scroll > li.product {
    float: none !important;
    flex: 0 0 58% !important;
    width: 58% !important;
    min-width: 58% !important;
    max-width: 58% !important;
    margin-right: 0 !important;
  }
}
@media (max-width: 767px) {
  .sky-announcement {
    height: 38px !important;
    overflow: hidden !important;
    padding: 0 6px !important;
  }

  .sky-announcement-item {
    width: 100% !important;
    left: 0 !important;
    right: 0 !important;
    padding: 0 6px !important;
    box-sizing: border-box !important;
    text-align: center !important;
    font-size: 12px !important;
    line-height: 38px !important;
    white-space: nowrap !important;
  }
}

